entries[442987] = { ["name"] = "Sprühender Blutsturz", ["text"] = "300 Meter Reichweite\nSofort\nDer blutgebundene Schrecken erschafft auf jeder Seite zwei Geysire aus Schwarzblut, die sich 20 Sek. lang langsam um sich selbst drehen. Wer in einem Geysir steht, erleidet alle 0.25 Sek. 17268946 Schattenschaden." }
entries[442988] = { ["name"] = "Magischer Mulch", ["text"] = "Wirken in 2 sek.\nReagenzien:\nMykopracht (5)\nSpezialisierung:\nBotanik - Mulchherstellung\n\nMagischer Mulch\nWird beim Aufheben gebunden\nBenutzen: Bereitet den Mulch für dessen Verwendung vor. Bedeckt damit Eure nächsten Kräuter, die Ihr sammeln möchtet, um eine mittlere Menge Finesse zu erhalten. Ihr könnt immer nur jeweils eine Portion Mulch verwenden.\n70\nBenötigt Kräuterkunde von Khaz Algar\n(1)" }
entries[442989] = { ["name"] = "Verzauberter Mulch", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeylinienrückstände (2), Mykopracht (10)\nSpezialisierung:\nBotanik - Mulchherstellung (20)\n\nVerzauberter Mulch\nWird beim Aufheben gebunden\nBenutzen: Bereitet den Mulch für dessen Verwendung vor. Bedeckt damit Eure nächsten Kräuter, die Ihr sammeln möchtet, um eine große Menge Finesse zu erhalten. Ihr könnt immer nur jeweils eine Portion Mulch verwenden.\n70\nBenötigt Kräuterkunde von Khaz Algar\n(1)" }
entries[442990] = { ["name"] = "Machterfüllter Mulch", ["text"] = "Wirken in 2 sek.\nReagenzien:\nGrünliche Sporen (4), Mykopracht (15)\nSpezialisierung:\nBotanik - Mulchherstellung (40)\n\nMachterfüllter Mulch\nWird beim Aufheben gebunden\nBenutzen: Bereitet den Mulch für dessen Verwendung vor. Bedeckt damit Eure nächsten Kräuter, die Ihr sammeln möchtet, um eine riesige Menge Finesse zu erhalten. Ihr könnt immer nur jeweils eine Portion Mulch verwenden.\n70\nBenötigt Kräuterkunde von Khaz Algar\n(1)" }
