entries[442994] = { ["name"] = "Entfesselter Schwarm", ["text"] = "Wirken in 3 sek.\nAnub'arash entfesselt einen Schwarm beißender Insekten, der allen Spielercharakteren 8 Sek. lang alle 1 Sek. 546850 Naturschaden zufügt. Dieser Effekt wird mit der Zeit stärker." }
entries[442995] = { ["name"] = "Schwarmüberraschung", ["text"] = "60 Meter Reichweite\nWirken in 3 sek.\nFügt Gegnern in der Nähe 2909339 körperlichen Schaden zu. Betroffene Spielercharaktere erleiden 30 Sek. lang 10% erhöhten Schaden durch 'Schwarmüberraschung'." }
