entries[442999] = { ["name"] = "Phalanx des Generals", ["text"] = "Sofort\nVerleiht 10 Sek. lang Immunität gegen jeglichen Schaden." }
entries[443001] = { ["name"] = "Toxischer Netzblitz", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nDer Zaubernde verschießt ein dichtes Paket aus Netzen und Gift auf sein aktuelles Ziel und fügt ihm so Naturschaden sowie zusätzlich all 1 Sek. Naturschaden zu und verringert seine Bewegungsgeschwindigkeit um 35%. Hält 5 Sek. lang an." }
