entries[443019] = { ["name"] = "Magischer Mulch", ["text"] = "Wirken in 1.5 sek.\nBereitet den Mulch für dessen Verwendung vor. Bedeckt damit Eure nächsten Kräuter, die Ihr sammeln möchtet, um eine mittlere Menge Finesse zu erhalten. Ihr könnt immer nur jeweils eine Portion Mulch verwenden." }
