entries[443027] = { ["name"] = "Eisengewebter Tornado", ["text"] = "Wirken in 3 sek.\nDer Zaubernde schwingt eine umwobene Waffe und hüllt sich in einen Wirbelwind aus rasiermesserscharfen Netzen. Der Wirbelwind trifft zweimal und fügt Spielercharakteren innerhalb von 8 Metern körperlichen Schaden zu." }
entries[443028] = { ["name"] = "Erhabene Leitung", ["text"] = "5% von GrundmanaKanalisiert (Wirken in 4 sek.) 1.5 min Abklingzeit\nWindläufer\nDie Himmlischen Erhabenen ermächtigen Euch, im Verlauf von 4 Sek. [(1100% der Zaubermacht) * 5] Heilung auf bis zu 5 verletzte Verbündete und [(1100% der Angriffskraft) * 5] Naturschaden auf Gegner im Umkreis von 15 Metern zu wirken und gleichmäßig auf sie zu verteilen. Heilung und Schaden werden pro getroffenem Gegner um 6% erhöht, bis zu einem Maximum von 30%.\n\nIhr könnt Euch während des Kanalisierens bewegen, aber das Wirken anderer Heil- oder Schadenszauber hebt diesen Effekt auf.\n\nNebelwirker\nDie Himmlischen Erhabenen ermächtigen Euch, im Verlauf von 4 Sek. [(1100% der Zaubermacht) * 5] Heilung auf bis zu 5 verletzte Verbündete und [(1100% der Angriffskraft) * 5] Naturschaden auf Gegner im Umkreis von 20 Metern zu wirken und gleichmäßig auf sie zu verteilen. Heilung und Schaden werden pro getroffenem Gegner um 6% erhöht, bis zu einem Maximum von 30%.\n\nIhr könnt Euch während des Kanalisierens bewegen, aber das Wirken anderer Heil- oder Schadenszauber hebt diesen Effekt auf." }
entries[443031] = { ["name"] = "Griff aus den Weiten", ["text"] = "Sofort\nDer blutgebundene Schrecken konzentriert das Ungehörige auf mehrere Spielercharaktere, sodass 12 Sek. lang alle 1 Sek. Tentakel an ihrer Position entstehen.\n\nJedes Tentakel bricht nach 3 Sek. aus und fügt allen Spielercharakteren innerhalb von 4 Metern 3453789 Schattenschaden zu." }
