entries[443036] = { ["name"] = "Eisengewebter Tornado", ["text"] = "Sofort\nDer Zaubernde schwingt eine umwobene Waffe und hüllt sich in einen Wirbelwind aus rasiermesserscharfen Netzen. Der Wirbelwind trifft zweimal und fügt Spielercharakteren innerhalb von 8 Metern körperlichen Schaden zu." }
entries[443037] = { ["name"] = "Atticas Höhlenfackel", ["text"] = "Sofort\nEin starkes Licht, das für kurze Zeit scheint und verborgene Gegner und Gegenstände in der Kaltschattenhöhle aufdecken kann.\n\nSolange das Licht scheint, könnt Ihr nicht in Verstohlenheit übergehen." }
entries[443038] = { ["name"] = "Erhabene Leitung", ["text"] = "Sofort\n[ Nebelwirker : Die Himmlischen Erhabenen ermächtigen Euch, im Verlauf von 4 Sek. [(1100% der Zaubermacht) * 5] Heilung auf bis zu 5 verletzte Verbündete und [(1100% der Angriffskraft) * 5] Naturschaden auf Gegner im Umkreis von 20 Metern zu wirken und gleichmäßig auf sie zu verteilen. Heilung und Schaden werden pro getroffenem Gegner um 6% erhöht, bis zu einem Maximum von 30% /\n\nWindläufer\nDie Himmlischen Erhabenen ermächtigen Euch, im Verlauf von 4 Sek. [(1100% der Zaubermacht) * 5] Heilung auf bis zu 5 verletzte Verbündete und [(1100% der Angriffskraft) * 5] Naturschaden auf Gegner im Umkreis von 15 Metern zu wirken und gleichmäßig auf sie zu verteilen. Heilung und Schaden werden pro getroffenem Gegner um 6% erhöht, bis zu einem Maximum von 30% ]\nIhr könnt Euch während des Kanalisierens bewegen, aber das Wirken anderer Heil- oder Schadenszauber hebt diesen Effekt auf." }
