entries[443274] = { ["name"] = "Instabile Infusion", ["text"] = "300 Meter Reichweite\nSofort\n' Instabile Infusion ' führt dazu, dass Blutverderber Ovi'nax gefährliche Schattenenergie ausstrahlt, wodurch alle 7.5 Sek. 287816 Schattenschaden verursacht und 490734 ihrer erhaltenen Heilung absorbiert wird.\nDieser Effekt ist stapelbar." }
entries[443275] = { ["name"] = "Blutwoge", ["text"] = "Unbegrenzte Reichweite\nSofort\nDas Koaglamat brüllt, fügt Spielercharakteren innerhalb von 8 Metern 9697798 Schattenschaden zu und erzeugt an seinem Standort eine größer werdende Lache aus Schwarzblut. Solange Spielercharaktere sich innerhalb dieser Lachen befinden, erleiden sie alle 1 Sek. 1697922 Schattenschaden und ihre Bewegungsgeschwindigkeit wird um 35% verringert." }
