entries[443328] = { ["name"] = "Umhüllen", ["text"] = "5% von Grundmana 25 Meter Reichweite\nSofort 27 sek. Abklingzeit\n1 Aufladung\nVerheerung\nUmhüllt Euer Ziel mit Drachenflammen, die ihm (962% der Zaubermacht) Feuerschaden zufügen oder es um (1020% der Zaubermacht) Gesundheit heilen. Für jeden Eurer regelmäßigen Effekte auf dem Ziel wird die Effektivität um 20% erhöht.\n\nSetzt voraus, dass 'Feueratem' für das Ziel aktiv ist.\n\nBewahrung\nUmhüllt Euer Ziel mit Drachenflammen, die ihm (962% der Zaubermacht) Feuerschaden zufügen oder es um (1020% der Zaubermacht) Gesundheit heilen. Für jeden Eurer regelmäßigen Effekte auf dem Ziel wird die Effektivität um 20% erhöht.\n\nSetzt voraus, dass 'Traumatem' oder 'Feueratem' für das Ziel aktiv ist." }
entries[443329] = { ["name"] = "Umhüllen", ["text"] = "25 Meter Reichweite\nSofort\nUmhüllt Euer Ziel mit Drachenflammen, die ihm (962% der Zaubermacht) Feuerschaden zufügen oder es um (1020% der Zaubermacht) Gesundheit heilen. Für jeden Eurer regelmäßigen Effekte auf dem Ziel wird die Effektivität um 20% erhöht.\n\nSetzt voraus, dass [ Bewahrung : 'Traumatem' oder 'Feueratem' /\n\nVerheerung\n'Feueratem' ] für das Ziel aktiv ist." }
