entries[443430] = { ["name"] = "Seidenbindung", ["text"] = "100 Meter Reichweite\nWirken in 1 sek.\nBindet ein Ziel mit kräftiger Seide. Fügt ihm 1212225 Naturschaden zu und reduziert seine Bewegungsgeschwindigkeit während der Kanalisierung pro Sekunde um 20%.\n\nWenn die Kanalisierung erfolgreich abgeschlossen wird, wird das Ziel vollständig gebunden und 4 Sek. lang betäubt." }
