entries[443433] = { ["name"] = "Gedankenverdreher", ["text"] = "50 Meter Reichweite\nWirken in 3.5 sek.\nVerdreht die Gedanken eines Spielercharakters mit dunkler Magie, um Spielercharakteren innerhalb von 4 Metern um ihn herum 1939560 Schattenschaden zuzufügen.\n\nDie verdrehten Gedanken halten 30 Sek. lang an und fügen Spielercharakteren, die im Bereich bleiben, alle 1.5 Sek. weitere 1939560 Schattenschaden zu." }
entries[443434] = { ["name"] = "Gedankenverdreher", ["text"] = "300 Meter Reichweite\nSofort\nVerdreht die Gedanken eines Spielercharakters mit dunkler Magie, um Spielercharakteren innerhalb von 4 Metern um ihn herum 1939560 Schattenschaden zuzufügen.\n\nDie verdrehten Gedanken halten 30 Sek. lang an und fügen Spielercharakteren, die im Bereich bleiben, alle 1.5 Sek. weitere 1939560 Schattenschaden zu." }
