entries[443436] = { ["name"] = "Schatten des Zweifels", ["text"] = "Wirken in 1 sek.\nLässt einen Spielercharakter zweifeln und fügt ihm so 8 Sek. lang alle 1 Sek. 1091002 Schattenschaden zu.\n\nBei Ablauf oder Entfernung des Effekts brechen die Zweifel aus dem Ziel hervor, fügen allen getroffenen Spielercharakteren 5091344 Schattenschaden zu und betäuben sie für 3 Sek." }
