entries[443441] = { ["name"] = "Irdene Kommunion", ["text"] = "'Erdschild' verfügt über 3 zusätzliche Aufladungen und heilt Euch um 25% mehr Gesundheit." }
entries[443442] = { ["name"] = "Naturgegebene Harmonie", ["text"] = "Verringert die Abklingzeit von 'Wächter der Natur' um 15 Sek. und bewirkt, dass 10% Eurer maximalen Gesundheit zusätzlich geheilt werden." }
entries[443444] = { ["name"] = "Hört meinen Ruf", ["text"] = "Ahnen bleiben 4 Sek. länger bestehen." }
entries[443445] = { ["name"] = "Routinekommunikation", ["text"] = "Wiederherstellung\n'Springflut' hat eine Chance von 15%, für 6 Sek. einen Ahnen an Eure Seite zu rufen.\n\nElementar\nEure Einsätze von 'Blitzschlag', 'Lavaeruption', 'Kettenblitzschlag', 'Eisfuror' und 'Frostschock' haben eine Chance von 8%, für 6 Sek. einen Ahnen an Eure Seite zu rufen." }
entries[443446] = { ["name"] = "Letzter Ruf", ["text"] = "Elementar\nWenn ein Ahne abtritt, setzt er 'Elementarschlag' gegen einen Gegner in der Nähe ein.\n\nWiederherstellung\nWenn ein Ahne abtritt, setzt er 'Hydroblase' gegen einen verwundeten Verbündeten in der Nähe ein.\n\nHydroblase\nUmgibt Euer Ziel 15 Sek. lang mit einer schützenden Wasserblase.\n\nDer Schild absorbiert den nächsten eintreffenden Schaden in Höhe von 0, aber die absorbierte Menge nimmt im Laufe seiner Dauer kontinuierlich bis auf 0 ab." }
entries[443447] = { ["name"] = "Mahlstrom-Überlegenheit", ["text"] = "Elementar\nErhöht den Schaden von 'Erdschock', 'Elementarschlag' und 'Erdbeben' um 25%.\n\nErhöht die Heilung von 'Heilende Woge' und 'Kettenheilung' um 25%.\n\nWiederherstellung\nErhöht die Heilung von 'Welle der Heilung', 'Heilende Woge', 'Lebensquell', 'Platzregen' und 'Kettenheilung' um 25%." }
entries[443448] = { ["name"] = "Urzeitliche Kapazität", ["text"] = "Wiederherstellung\nErhöht das maximale Mana um 10%.\n\n'Flutwellen' ist jetzt bis zu 4-mal stapelbar.\n\nElementar\nErhöht den maximalen Mahlstrom um 25" }
entries[443449] = { ["name"] = "Geballte Weisheit", ["text"] = "Die Zauber Eurer Ahnen sind 25% mächtiger." }
entries[443450] = { ["name"] = "Ruf der Urahnen", ["text"] = "Elementar\n'Urzeitliche Welle' ruft für 6 Sek. einen Ahnen an Eure Seite. Wann immer Ihr einen Heil- oder Schadenszauber wirkt, wirkt der Ahne einen ähnlichen Zauber.\n\nWiederherstellung\nDas Profitieren von 'Wogen' ruft für 6 Sek. einen Ahnen an Eure Seite.\n\nDer Einsatz von 'Leben entfesseln' ruft für 12 Sek. einen Ahnen an Eure Seite.\n\nWann immer Ihr einen Heil- oder Schadenszauber wirkt, wirkt der Ahne einen ähnlichen Zauber." }
entries[443451] = { ["name"] = "Opfergabe aus dem Jenseits", ["text"] = "Elementar\nWenn ein Ahne herbeigerufen wird, verringert er die Abklingzeit von 'Feuerelementar' und 'Sturmelementar' um 5 Sek.\n\nWiederherstellung\nWenn ein Ahne herbeigerufen wird, verringert er die Abklingzeit von 'Springflut' um 3 Sek." }
