entries[443454] = { ["name"] = "Schnelligkeit der Ahnen", ["text"] = "Sofort 30 sek. Abklingzeit\nEuer nächster Einsatz eines Heil- oder Schadenzaubers ist ein Spontanzauber, kostet kein Mana und verursacht 10% mehr Schaden und Heilung.\n\nWenn Ihr 'Schnelligkeit der Natur' beherrscht, wird sie durch 'Schnelligkeit der Ahnen' ersetzt, und 'Schnelligkeit der Ahnen' ruft für 6 Sek. einen Ahnen an Eure Seite." }
entries[443455] = { ["name"] = "Gebet des geläuterten Zorns", ["text"] = "Sofort\nWenn Ihr das nächste Mal getroffen werdet, entfesselt Ihr ' Geläuterter Zorn '.\n\nGeläuterter Zorn :\nFügt Gegnern innerhalb von 8 Metern 2625000 körperlichen Schaden zu und betäubt sie für 3 Sek." }
entries[443456] = { ["name"] = "Gebet des geläuterten Stolzes", ["text"] = "Sofort\nErlangt außerhalb des Kampfes ' Geläuterter Stolz '.\n\nGeläuterter Stolz :\nVerschwindet von der Bildfläche in die Verstohlenheit. Euer nächster Angriff erzielt garantiert einen kritischen Treffer." }
entries[443457] = { ["name"] = "Gebet des geläuterten Hasses", ["text"] = "Sofort\nDer nächste Angriff, der Eure Gesundheit unter 35% bringt, löst ' Geläuterter Hass ' aus.\n\nGeläuterter Hass :\nStellt Eure Gesundheit, Euren Elan und Eure Klassenressourcen vollständig wieder her." }
