entries[443465] = { ["name"] = "Fass mit Feuerwerkskörpern", ["text"] = "8 Meter Reichweite\nSofort 1 Stunde Abklingzeit\nStellt ein gefährliches Fass mit Feuerwerkskörpern auf, das 5 Min. Sek. lang stehen bleibt, um für Euch und Eure Freunde den Nachthimmel grell zu erleuchten!\n\nAndere Spielercharaktere können sich das Feuerwerk auch ansehen, indem sie das Fass angreifen.\n\nWährend der Feierlichkeiten von betrunkenen Goblins ist die Abklingzeit verringert." }
