entries[443525] = { ["name"] = "Pfeife des Kerzenleiters", ["text"] = "Ca. 1.5 Procs pro Minute\nEure Angriffe haben eine Chance, eine Koboldlore auf Euer Ziel zu lenken. Diese entsendet einen rasenden Trupp, der mit Gegnern zusammenstößt und ( 1 * 1547 ) körperlichen Schaden verursacht, die unter allen getroffenen Gegnern aufgeteilt werden." }
entries[443526] = { ["name"] = "Vorahnung des Trostes", ["text"] = "100 Meter Reichweite\nSofort\nEuer nächster Einzelzielheilzauber gewährt Eurem Ziel einen Schild, der 0 Schaden absorbiert und den erlittenen Schaden 15 Sek. lang um 15% verringert." }
entries[443527] = { ["name"] = "Verziertes Lohenzarwachs", ["text"] = "Ca. 2 Procs pro Minute\nEure Zauber haben eine Chance, das Wachs zu verzaubern, um für 15 Sek. eine lodernde Kerze zu erzeugen, die Eure Vielseitigkeit um 122 und, während Ihr in ihrem Licht bleibt, weiter um 32 erhöht." }
