entries[443529] = { ["name"] = "Stichel des Kerzenkönigs", ["text"] = "40 Meter Reichweite\nSofort 1.5 min Abklingzeit\nSchnitzt eine Wachskopie Eures Ziels, die 50% des erlittenen Schadens absorbiert. Durch die Absorption erhitzt sich das Wachs, bis es nach Absorption von 6705 Schaden schmilzt." }
entries[443530] = { ["name"] = "Fragment der Dunkelheit", ["text"] = "Ca. 2 Procs pro Minute\nEure Fähigkeiten haben eine Chance, die Dunkelheit zu Euch zu rufen, wodurch sich Eure Hauptwert um 19 erhöht, bis zu ( 19 * 5).\n\nBei Erreichen voller Kraft wird die Dunkelheit entfesselt und verursacht ( 1 * 1789 * 15 / 3) Schattenschaden, die zwischen Gegnern in der Nähe im Verlauf von 15 Sek. aufgeteilt werden, bevor sie wieder in das Fragment verblasst." }
entries[443531] = { ["name"] = "Anstachelndes Licht", ["text"] = "Sofort 2 min Abklingzeit\nErhebt Euer Siegel zum Licht und erhöht so Euren höchsten Sekundärwert 20 Sek. lang um 260 . Eure Tat inspiriert andere Siegelträger Eurer Gruppe in der Nähe und gewährt ihnen 20 Sek. lang 7 desselben Werts." }
entries[443532] = { ["name"] = "In Dunkelheit gebunden", ["text"] = "Sofort\n[ Blut : 'Siedendes Blut' fügt seinem Hauptziel 10% mehr Schaden /\n\nFrost\nDurch 'Raureif' ermächtigte 'Heulende Böen' fügt seinem Hauptziel 60% mehr Schaden ] zu und ist jetzt Schattenfrost.\n\nSchattenfrostschaden gewährt 2 Stapel für 'Mal des Schnitters' oder 4 Stapel bei kritischen Treffern." }
entries[443533] = { ["name"] = "Foliant der Hingabe des Lichts", ["text"] = "Ihr blättert zu den 50 Versen der inneren Abhärtung weiter und lest sie, während Ihr angegriffen werdet.\n'Innere Abhärtung' erhöht Eure Rüstung um 136 und gewährt Euren Angriffen eine Chance, einen Schutz zu beschwören, der 3376 Magieschaden absorbiert. Sobald Ihr fertig seid, blättert Ihr zum nächsten Kapitel weiter.\n\nGilt nur für Tankspezialisierungen.\n(500ms Abklingzeit)" }
entries[443534] = { ["name"] = "Strahlen", ["text"] = "Sofort\nIhr strahlt, was die Effizienz Eures Verses erhöht." }
entries[443535] = { ["name"] = "Foliant der Hingabe des Lichts", ["text"] = "Sofort 1.5 min Abklingzeit\nBlättert mit erhöhter Strahlung durch die Textstellen des Folianten." }
entries[443536] = { ["name"] = "Explodierender Lichtsplitter", ["text"] = "35 Meter Reichweite\nSofort 2 min Abklingzeit\nBeschwört eine berstende Lichtbrut, die ihre Gesundheit opfert, um Lichtstöße zu entfesseln, die 1446 Heiligschaden verursachen, der alle 2 Sekunden auf Gegner in der Nähe aufgeteilt wird, solange die Brut lebt." }
entries[443537] = { ["name"] = "Leerenpaktstein", ["text"] = "Ca. 2 Procs pro Minute\nEure Angriffe haben eine Chance, den Pakt anzurufen und eine Explosion auszulösen, die ( 1 * 897 ) Schattenschaden verursacht, die auf Gegner in der Nähe aufgeteilt werden, und Euer Tempo 10 Sek. lang um 36 erhöht.\n\nEuer Tod beendet den Pakt und führt zu einer gewaltigen Explosion." }
entries[443538] = { ["name"] = "Ermächtigender Kristall von Anub'ikkaj", ["text"] = "Ca. 1.55 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, eine wachsende Ermächtigung aus dem Kristall freizusetzen, die einen zufälligen Sekundärwert 20 Sek. lang um 131 erhöht." }
entries[443539] = { ["name"] = "Mereldars Tribut", ["text"] = "50 Meter Reichweite\nSofort\nEntfesselt einen Tribut aus heiligem Licht auf das Ziel und fügt ihm ( 1 * 1368 ) Heiligschaden zu. Die nächsten 5 Verbündeten, die das Ziel angreifen, erhalten den 'Segen von Mereldar', was ihre Vielseitigkeit 10 Sek. lang um 62 erhöht." }
entries[443541] = { ["name"] = "Kokonbrut von Ara-Kara", ["text"] = "Ca. 2.5 Procs pro Minute\nEure Fähigkeiten haben eine Chance, den Kokon zu bewegen, der ein Ei freigibt, das Eure Hauptwert um 15 erhöht. Jedes Ei schlüpft nach 1 Min. Die neue Brut greift Euer nächstes Ziel an und fügt ihm im Verlauf von 8 Sek. ( 1 * 80 * 8) Naturschaden zu.\n(100ms Abklingzeit)" }
entries[443544] = { ["name"] = "Aggressionsablenkungsmodul", ["text"] = "Eure Spottfähigkeiten aktivieren die brechende Energie des Moduls und schützen Euch vor 50% des erlittenen Schadens, bis zu 7648 . Dies kann nur einmal pro 1 Min. geschehen.\n\nGilt nur für Tankspezialisierungen.\n(1Min. Abklingzeit)" }
entries[443545] = { ["name"] = "Endlose Schwarmdrüse", ["text"] = "Ca. 6 Procs pro Minute\nDie Drüse setzt Pheromone frei, die einen endlosen Schwarm von Insekten anlocken, die Euch umkreisen. Wenn Ihr Schaden erleidet, habt Ihr eine hohe Chance auf einen Gegenschlag, der über 6 Sek. ( 69 * 6) Naturschaden verursacht und den Euch zugefügten Schaden um 96 reduziert." }
entries[443549] = { ["name"] = "Edikt des Ernters", ["text"] = "100 Meter Reichweite\nSofort\nEure Schadenszauber und -fähigkeiten haben eine Chance, eine Kugel aus instabilem Schwarzblut auf Euer Ziel zuschweben zu lassen, die beim Aufprall explodiert und ( 1 * 1418 ) Schattenschaden verursacht, die zwischen allen Gegnern in der Nähe aufgeteilt werden. Wenn Ihr die Kugel abfangt, könnt Ihr deren Macht entziehen und damit Eure Meisterschaft 15 Sek. lang um 156 erhöhen." }
entries[443552] = { ["name"] = "Erdrückende Ansprache", ["text"] = "Sofort 2 min Abklingzeit\nSchwenkt den Kehlkopf in der Luft, um einen quälenden Chor zu entfesseln, der Gegnern in der Nähe im Verlauf von 3 Sek. ( 1 * 1480 * 3) Schattenschaden zufügt. Euer Flüstern schließt sich dem Chor an und erhöht den Schaden, bevor er verstummt." }
entries[443553] = { ["name"] = "Elchansturmrückstoß", ["text"] = "Unbegrenzte Reichweite\nSofort\nStürmt auf das Ziel zu, rammt es und stößt es zurück." }
entries[443556] = { ["name"] = "Doppelfangbesteck", ["text"] = "Sofort 2 min Abklingzeit\nÖffnet den Beutel und zückt die Schattenklinge von Nx, um schnell auf Gegner vor Euch loszugehen und allen getroffenen Gegnern ( 1 * 585 ) Schattenschaden zuzufügen.\n\nIhr könnt den Beutel bis zu zwei weitere Male innerhalb von 20 Sek. benutzen, bevor er sich selbst versiegelt und seinen Inhalt magisch auflädt." }
entries[443557] = { ["name"] = "Zähflüssiges Koaglam", ["text"] = "Eure überschüssige Heilung lockt Schattenenergie aus der Nähe zu Eurer Gruppe, die bis zu 213 Heilung speichert und die Gesundheit des Ziels wiederherstellt, wenn es Schaden erleidet." }
entries[443558] = { ["name"] = "Geronnene Membran", ["text"] = "46 Meter Reichweite\nSofort 1 min Abklingzeit\nKanalisiert die Kraft des Koaglmats, indem die gesamte aktuelle Schattenenergie auf Euer Ziel konzentriert wird." }
entries[443559] = { ["name"] = "Rankendes Mixtorium", ["text"] = "Ca. 2 Procs pro Minute\nEure Zaubersprüche können Euch dazu inspirieren, an einem Verbündeten zu experimentieren und ihn auf unvorhergesehene Weise 20 Sek. lang zu verbessern." }
entries[443560] = { ["name"] = "Schnell und qualvoll", ["text"] = "Blut\nWenn 'Seeleneruption' keine Gegner trifft, erlangt Ihr für 8 Sek. 10% Stärke.\n\n'Welle der Seelen' ist gegen das Hauptziel Eures 'Mal des Schnitters' 100% effektiver.\n\nFrost\nWenn 'Seeleneruption' keine Gegner trifft, erlangt Ihr für 8 Sek. 5% Stärke.\n\n'Welle der Seelen' ist gegen das Hauptziel Eures 'Mal des Schnitters' 50% effektiver." }
entries[443561] = { ["name"] = "Verdächtige Spritze tragen" }
entries[443562] = { ["name"] = "Nähschere tragen" }
entries[443563] = { ["name"] = "Rostmilben freisetzen", ["text"] = "5 Meter Reichweite\nWirken in 1.5 sek.\nÖffnet ein Glas mit Rostmilben, damit sie das Schmiedewerkzeug zerfressen." }
entries[443564] = { ["name"] = "Qualvoller Tod", ["text"] = "Frost\nNachdem 'Mal des Schnitters' explodiert, kosten Eure nächsten [Quellwert] Einsätze von 1 [Quellwert]:Runen;; und beschwört 2 Sensen, die Eure Gegner trifft:treffen;.\n\nDie erste Sense fügt Eurem Ziel (407.975% der Angriffskraft) Schattenfrostschaden zu und hat eine Chance von 100%, eine 'Tötungsmaschine' zu gewähren. Die zweite Sense fügt allen Gegnern um Euer Ziel für (178.723% der Angriffskraft) Schattenfrostschaden zu [und belegt sie mit 'Frostfieber']. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nBlut\nNachdem 'Mal des Schnitters' explodiert, kosten Eure nächsten [Quellwert] Einsätze von 1 [Quellwert]:Runen;; und beschwört 2 Sensen, die Eure Gegner trifft:treffen;.\n\nDie erste Sense fügt Eurem Ziel (349.069% der Angriffskraft) Schattenfrostschaden zu und hat eine Chance von 100%, lang 2.0 Sek. einen 'Knochensturm' zu ernten. Die zweite Sense fügt allen Gegnern um Euer Ziel für (186.17% der Angriffskraft) Schattenfrostschaden zu [und belegt sie mit 'Frostfieber']. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.", ["unresolvedValues"] = true }
entries[443565] = { ["name"] = "Fackel werfen", ["text"] = "20\n- 30\nMeter Reichweite\nWirken in 1.5 sek.\nVerbrennt die Leiche eines gefallenen Verteidigers. Lasst nichts für die Neruber übrig, was sie schänden könnten!" }
entries[443566] = { ["name"] = "Chi-Jis Schnelligkeit", ["text"] = "Eure Bewegungsgeschwindigkeit ist während 'Erhabene Leitung' um 75% und, nachdem Ihr von einem beliebigen Erhabenen unterstützt wurdet, 3 Sek. lang um 15% erhöht." }
entries[443568] = { ["name"] = "Schicksalsweber" }
entries[443569] = { ["name"] = "Chi-Jis Schnelligkeit", ["text"] = "Sofort\nEure Bewegungsgeschwindigkeit ist während 'Erhabene Leitung' um 75% und, nachdem Ihr von einem beliebigen Erhabenen unterstützt wurdet, 3 Sek. lang um 15% erhöht." }
entries[443570] = { ["name"] = "Steingebundene Laterne", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHaufen rostigen Schrotts (50), Handvoll Bismutbolzen (32), Launische Verdrahtung (6), Kreisende Ausrüstung (12), Entropieverstärker (2)\nQuest:\nDie Schmiede der Erinnerungen\nZone:\nInsel von Dorn\n\nSteingebundene Laterne\nSpielzeug\nBenutzen: Platziert eine Laterne, um Eure Umgebung zu erleuchten und Euch zu beruhigen. Die von ihr erzeugte Wärme reicht außerdem gerade so für das Kochen einer Mahlzeit aus." }
entries[443571] = { ["name"] = "Innerer Kompass", ["text"] = "Ihr wechselt zwischen den Ausrichtungen, nachdem Euch ein Himmlischer Erhabener unterstützt hat, und erhöht einen entsprechenden Sekundärwert um 2%.\n\nKranichstil :\nTempo\n\nTigerstil :\nKritischer Treffer\n\nOchsenstil :\nVielseitigkeit\n\nSchlangenstil :\nMeisterschaft" }
