entries[443586] = { ["name"] = "Dunkelkrallen", ["text"] = "Sofort\n[ Blut : 'Markzerfetzer' und 'Herzstoß' haben /\n\nFrost\n'Tötungsmaschine' oder 'Raureif' ] hat eine Chance von 25%, 3 Stapel von 'Eisige Klauen' zu gewähren und dessen maximale Stapel für 6 Sek. um denselben Betrag zu erhöhen.\n\nWährend 'Eisige Klauen' aktiv ist, zählen Fähigkeiten, die Runenmacht kosten, auch als Schattenfrost." }
entries[443589] = { ["name"] = "Einigkeit im Inneren", ["text"] = "'Erhabene Leitung' kann innerhalb ihrer Dauer einmal erneut gewirkt werden, um alle Himmlischen Erhabenen anzurufen, Euch mit 200% Effektivität zu unterstützen.\n\n'Einigkeit im Inneren' wird automatisch gewirkt, wenn 'Erhabene Leitung' endet, sofern es nicht vor dessen Ablauf verwendet wird." }
entries[443590] = { ["name"] = "Schicksalsfaden", ["text"] = "Sofort\nEure schädlichen und hilfreichen Zauber haben eine Chance, für 5 Sek. einen Schicksalsfaden zwischen Euch und Eurem Ziel zu weben. Angeleinte Verbündete erhalten einen Bonus von 47 auf Ihren Primärwert, solange der Faden hält, und Gegner erleiden ( 1 * 975 ) kosmischen Schaden, wenn der Faden reißt." }
entries[443591] = { ["name"] = "Einigkeit im Inneren", ["text"] = "40 Meter Reichweite\nSofort\n'Erhabene Leitung' kann innerhalb ihrer Dauer einmal erneut gewirkt werden, um alle Himmlischen Erhabenen gleichzeitig anzurufen, Euch mit 200% Effektivität zu unterstützen." }
entries[443592] = { ["name"] = "Einigkeit im Inneren", ["text"] = "Sofort\n'Erhabene Leitung' kann innerhalb ihrer Dauer einmal erneut gewirkt werden, um alle Himmlischen Erhabenen gleichzeitig anzurufen, Euch mit 443591% Effektivität zu unterstützen." }
