entries[443612] = { ["name"] = "Grausiges Auswürgen", ["text"] = "300 Meter Reichweite\nSofort\nDer blutgebundene Schrecken speit Schwarzblut in einen kegelförmigen Bereich vor sich, verursacht 2878158 Schattenschaden sowie 40 Sek. lang alle 2 Sek. 604413 zusätzlichen Schattenschaden. Von diesem Effekt betroffene Spielercharaktere blicken für einen kurzen Moment in das Ungehörige." }
entries[443614] = { ["name"] = "Flug des Roten Kranichs", ["text"] = "100 Meter Reichweite\nSofort\n[ Nebelwirker : 'Erquickender Jadewind' und 'Wirbelnder Kranichtritt' haben eine Chance, Chi-Ji zu 5 Verbündeten eilen zu lassen und jedes Ziel um (125% der Zaubermacht) Gesundheit zu heilen sowie Euch einen Stapel 'Manatee' zu gewähren ] [ Windläufer : 'Rauschender Jadewind' und 'Wirbelnder Kranichtritt' haben eine Chance, Chi-Ji Eure Energieregeneration 6 Sek. lang um 20% erhöhen und ihn dann zu 5 Gegnern eilen zu lassen und jedem getroffenen Ziel (200% der Angriffskraft) körperlichen Schaden zuzufügen ]" }
entries[443616] = { ["name"] = "Herz der Jadeschlange", ["text"] = "100 Meter Reichweite\nSofort\nWindläufer\n'Schlag des Windlords' ruft Yu'lon an, um die Abklingzeitrate von 'Furorfäuste', 'Schlag des Windlords', 'Tritt der aufgehenden Sonne', 'Fliegender Schlangentritt' und 'Wirbelnder Drachenschlag' um 75% zu erhöhen. Dieser Effekt hält 8 Sek. lang an.\n\nDie Kanalisierungszeit von 'Furorfäuste' ist um 50% verringert, während Yu'lon aktiv ist.\n\nNebelwirker\n'Sheiluns Gabe' ruft Yu'lon an, um die Abklingzeitrate von 'Erneuernder Nebel', 'Tritt der aufgehenden Sonne', 'Lebenskokon' und 'Donnerfokustee' um 75% zu erhöhen. Dieser Effekt hält basierend auf den verbrauchten Nebelwolken bis zu 8 Sek. lang an." }
