entries[443654] = { ["name"] = "Infizieren", ["text"] = "Unbegrenzte Reichweite\nSofort\nAnsurek injiziert ihrem aktuellen Ziel schattenerfüllte Eiersäcke und fügt ihm so 20147103 Schattenschaden sowie 11512630 körperlichen Schaden zu. Außerdem erleiden Opfer 4 Sek. lang alle 1 Sek. 2590342 Schattenschaden.\n\nBei Ablauf platzen die Säcke und es folgt ein ' Befallener Düsterausbruch '." }
