entries[443658] = { ["name"] = "Statische Aufladung", ["text"] = "40 Meter Reichweite\nSofort\nIhr speichert alle 10 Sek. 1481 Stapel von 'Statische Aufladung'. Wenn Ihr Euch bewegt, wird 'Statische Aufladung' freigesetzt und heilt Verbündete insgesamt um 3 Gesundheit bzw. fügt Gegnern insgesamt Schaden in Höhe dieses Werts zu. Die Heilung bevorzugt verletzte Verbündete. Gegner erleiden Schaden in Höhe der statischen Aufladung und Verbündete werden um 150% der statischen Aufladung geheilt." }
entries[443659] = { ["name"] = "Statische Aufladung", ["text"] = "Sofort\nSchiebt alle 3 Sek. [ 87 * (1 + Vielseitigkeit)] Heilung auf. Bewegung setzt die aufgeschobene Heilung frei und heilt Eure 3 am schwersten verletzten Verbündeten." }
