entries[443735] = { ["name"] = "Vereinigende Glut", ["text"] = "Ca. 2 Procs pro Minute\nBeim Heilen eines Verbündeten besteht eine Chance, dass Ihr beide eine vereinigende Glut erhaltet. Wenn sich zwei vereinigende Gluten berühren, brechen 'Vereinigende Flammen' daraus hervor.\n\n'Vereinigende Flammen' erhöht den höchsten Sekundärwert des Trägers um 1175 und bei anderen einen zufälligen Sekundärwert um 235 ." }
entries[443736] = { ["name"] = "Funke von Beledar", ["text"] = "60 Meter Reichweite\nCa. 2 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, die Kraft des Lichts auf Eure Gegner herabzurufen. Ein Funke von Beledar richtet und markiert sie und fügt ihnen 320 Strahlenschaden zu. Euer nächster Funke gegen Euer Ziel verbraucht das Mal, um 274 zusätzlichen Strahlenschaden zu verursachen." }
