entries[443739] = { ["name"] = "Splitterzauberkunst", ["text"] = "Arkan\nWenn Ihr 'Netherpräzision' verbraucht, beschwört Ihr 2 arkane Splitter .\n\nArkaner Splitter :\nBeschwört aus Arkanmagie ein scharfes Projektil, das (40.4% der Zaubermacht) Arkanschaden verursacht.\n\n'Arkane Splitter' bohren sich in ihr Ziel und verursachen 18 Sek. lang (40.4352% der Zaubermacht) Arkanschaden. Dieser Effekt ist stapelbar.\n\nFrost\nWenn Ihr 'Winterkälte' oder 'Eisige Finger' verbraucht, beschwört Ihr einen Frostsplitter .\n\nFrostsplitter :\nBeschwört aus Frostmagie ein scharfes Projektil, das (34.32% der Zaubermacht) Frostschaden verursacht.\n\nFrostsplitter bohren sich in ihr Ziel und verursachen 18 Sek. lang (34.2% der Zaubermacht) Frostschaden. Dieser Effekt ist stapelbar." }
entries[443740] = { ["name"] = "Eingebetteter Frostsplitter", ["text"] = "100 Meter Reichweite\nSofort\nBeschwört aus Frostmagie ein scharfes Projektil, das (34.32% der Zaubermacht) Frostschaden verursacht.\n\nFrostsplitter bohren sich in ihr Ziel und verursachen 18 Sek. lang (34.2% der Zaubermacht) Frostschaden. Dieser Effekt ist stapelbar." }
