entries[443742] = { ["name"] = "Splittersturm", ["text"] = "Frost\nWenn Ihr mindestens 8 aktive eingebettete Frostsplitter habt, wirkt Ihr automatisch einen 'Splittersturm' auf Euer Ziel.\n\nSplittersturm :\nZerschmettert alle eingebetteten Frostsplitter und verursacht sofort ihren verbleibenden regelmäßigen Schaden.\n\nBeschwört für jeden zerschmetterten Splitter einen Frostsplitter und entfesselt dann einen verheerenden Beschuss mit ihnen, der dem Ziel für jeden Splitter im 'Splittersturm' (34.32% der Zaubermacht) Frostschaden zufügt.\n\n'Splittersturm' hat eine Chance von 10%, 'Hirnfrost' auszulösen.\n\nArkan\nWenn Ihr mindestens 8 aktive eingebettete arkane Splitter habt, wirkt Ihr automatisch einen 'Splittersturm' auf Euer Ziel.\n\nSplittersturm :\nZerschmettert alle eingebetteten arkanen Splitter und verursacht sofort ihren verbleibenden regelmäßigen Schaden.\n\nBeschwört für jeden zerschmetterten Splitter einen arkanen Splitter und entfesselt dann einen verheerenden Beschuss mit ihnen, der dem Ziel für jeden Splitter im 'Splittersturm' (40.4% der Zaubermacht) Arkanschaden zufügt.\n\n'Splittersturm' hat eine Chance von 8%, 'Freizaubern' zu gewähren." }
entries[443743] = { ["name"] = "Gesegneter Waffengriff", ["text"] = "Ca. 1 Procs pro Minute\nWenn Ihr einem Ziel Schaden zufügt, besteht eine geringe Chance, die Macht des gesegneten Waffengriffs anzurufen und Euch 10 Stapel zu gewähren, die Euren höchsten Sekundärwert um 185 erhöhen. Diese Stapel nehmen im Verlauf von 30 Sek. wieder ab." }
entries[443745] = { ["name"] = "Splittersturm", ["text"] = "100 Meter Reichweite\nSofort\nFrost\nWenn Ihr mindestens 8 aktive eingebettete Frostsplitter habt, wirkt Ihr automatisch einen 'Splittersturm' auf Euer Ziel.\n\nSplittersturm :\nZerschmettert alle eingebetteten Frostsplitter und verursacht sofort ihren verbleibenden regelmäßigen Schaden.\n\nBeschwört für jeden zerschmetterten Splitter einen Frostsplitter und entfesselt dann einen verheerenden Beschuss mit ihnen, der dem Ziel für jeden Splitter im 'Splittersturm' (34.32% der Zaubermacht) Frostschaden zufügt.\n\n'Splittersturm' hat eine Chance von 10%, 'Hirnfrost' auszulösen.\n\nArkan\nWenn Ihr mindestens 8 aktive eingebettete arkane Splitter habt, wirkt Ihr automatisch einen 'Splittersturm' auf Euer Ziel.\n\nSplittersturm :\nZerschmettert alle eingebetteten arkanen Splitter und verursacht sofort ihren verbleibenden regelmäßigen Schaden.\n\nBeschwört für jeden zerschmetterten Splitter einen arkanen Splitter und entfesselt dann einen verheerenden Beschuss mit ihnen, der dem Ziel für jeden Splitter im 'Splittersturm' (40.4% der Zaubermacht) Arkanschaden zufügt.\n\n'Splittersturm' hat eine Chance von 8%, 'Freizaubern' zu gewähren." }
