entries[443760] = { ["name"] = "Verfinsternde Dunkelheit", ["text"] = "60 Meter Reichweite\nCa. 5 Procs pro Minute\nWenn Ihr Schaden verursacht, besteht eine Chance, einen Stapel von 'Verfinsternde Dunkelheit' zu erhalten. Bei 5 Stapeln explodiert die Dunkelheit und verursacht ( 1 * 1388 ) Schattenschaden, die auf alle Gegner in der Nähe aufgeteilt werden. Der Schaden erhöht sich pro Ziel für maximal 5 Ziele. Danach legen sich die Schatten auf Euch und verringern Eure Bewegungsgeschwindigkeit 5 Sek. lang um 15%.\n\nDies ist eine nerubische Verzierung." }
entries[443761] = { ["name"] = "Gevatter Tod" }
entries[443762] = { ["name"] = "Adrenalinschub", ["text"] = "Ca. 2 Procs pro Minute\nBeim Erleiden von Schaden besteht eine Chance, dass Ihr 'Adrenalinschub' erhaltet, sodass Eure Hauptwert um 24 erhöht, Eure Meisterschaft aber um 207 verringert wird. Hält 12 Sek. lang an.\n\nDies ist eine nerubische Verzierung.\n(15s Abklingzeit)" }
entries[443763] = { ["name"] = "Arkaner Splitter", ["text"] = "100 Meter Reichweite\nSofort\nBeschwört aus Arkanmagie ein scharfes Projektil, das (40.4% der Zaubermacht) Arkanschaden verursacht.\n\n'Arkane Splitter' bohren sich in ihr Ziel und verursachen 18 Sek. lang (40.4352% der Zaubermacht) Arkanschaden. Dieser Effekt ist stapelbar." }
entries[443764] = { ["name"] = "Umarmung der Glutbiene", ["text"] = "Ca. 3 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, eine schwebende Feuerpollenkugel in der Nähe zu erschaffen. Wenn Ihr in die Kugel tretet, sammelt Ihr sie auf, was Euren höchsten Sekundärwert 12 Sek. lang um 1045 erhöht. Bis zu 2 Verbündete, die in dieser Zeit in Eure Nähe treten, erhalten 12 Sek. lang 87 eines zufälligen Sekundärwerts." }
