entries[443770] = { ["name"] = "Windwirker", ["text"] = "Ca. 2 Procs pro Minute\nEure Bewegungsgeschwindigkeit ist um 5% erhöht und Ihr seid immun gegen Fallschaden. Eure Fähigkeiten haben eine Chance, 10 Sek. lang das Tempo Eurer Gruppenmitglieder um 409 zu erhöhen." }
entries[443771] = { ["name"] = "Windwirker", ["text"] = "100 Meter Reichweite\nSofort\nEure Fähigkeiten haben eine Chance, Euer Ziel mit 'Blitzableiter' zu belegen. Der kritische Trefferwert von Verbündeten wird 10 Sek. lang um 306 erhöht und Gegner erleiden 8 Sek. lang alle 2 Sek. 337 Naturschaden. Wenn 'Blitzableiter' abläuft, kehrt er zu Euch zurück und erhöht 10 Sek. lang Euren kritischen Trefferwert um 306 ." }
