entries[443931] = { ["name"] = "Feuerwirbel", ["text"] = "100 Meter Reichweite\nSofort\n- Flächenschaden um Zaubernden\n- Erzwungene Bewegung\n- Mobilität\n\n18 Sek. Abklingzeit\nUmhüllt Euch mit Flammen und stürmt vorwärts, um Gegnern Schaden zuzufügen, die Ihr passiert." }
entries[443933] = { ["name"] = "Giftblitz", ["text"] = "30 Meter Reichweite\nSofort\nDer Zaubernde schleudert einen mächtigen Giftklumpen auf sein aktuelles Ziel, fügt diesem Naturschaden zu und vergiftet es, sodass es 5 Sek. lang alle 1 Sek. zusätzlichen Naturschaden erleidet." }
