entries[443954] = { ["name"] = "Abluftschächte", ["text"] = "100 Meter Reichweite\nSofort\nBrokk kanalisiert Energie in die Maschine unter sich und aktiviert 6 Sek. lang deren Abluftschächte, was allen Spielercharakteren alle 1 Sek. 969780 Feuerschaden zufügt. Außerdem wird durchgehend ' Flammender Schrott ' im Bereich verteilt.\n\nWährend sie aktiv sind, fügen die Abluftschächte Spielercharakteren, die auf ihnen stehen, alle 1 Sek. 9697798 Feuerschaden zu." }
entries[443957] = { ["name"] = "Erdung", ["text"] = "Verringert den erlittenen Magieschaden um 75% und leitet den nächsten Schadenszauber, der einen Verbündeten innerhalb von 40 Metern anvisiert, auf Euch um.\n\n3 Sek. nach dem Erleiden von Magieschaden oder dem Umleiten eines Zaubers, wird dieser Effekt 20 Sek. lang unterdrückt." }
