entries[444005] = { ["name"] = "Champion des Reiters", ["text"] = "Beim Verbrauchen von Runen habt Ihr die Chance, 10 Sek. lang die Hilfe eines Reiters zu erhalten.\n\nMograine\nWirkt 'Tod und Verfall' an seiner Position. Der Effektbereich folgt seiner Bewegung.\n\nWeißsträhne\nWirkt 'Untot' auf Euer Ziel, was 24 Sek. lang alle 3 Sek. pro Stapel (9.15376% der Angriffskraft) Schattenfrostschaden verursacht. Wann immer 'Untot' Schaden verursacht, wird das Ziel mit einem weiteren Stapel belegt. Kann nicht erneuert werden.\n\nTrollbann\nWirkt 'Eisketten' auf Euer Ziel, was 8 Sek. lang dessen Bewegungsgeschwindigkeit um 40% verringert und den Schaden, den Ihr ihm zufügt, um 5% erhöht.\n\nNazgrim\nWährend Nazgrim aktiv ist, erhaltet Ihr 'Apokalyptische Eroberung', was Eure Stärke um 5% erhöht." }
entries[444008] = { ["name"] = "Der Tod reit' schneller", ["text"] = "In der Außenwelt könnt Ihr auch im Kampf auf Euer Todesstreitross von Acherus aufsitzen." }
