entries[444033] = { ["name"] = "Hunger von Weißsträhne", ["text"] = "Frost\nWenn 'Auslöschen' oder 'Frostsichel' einem Gegner Schaden zufügt, der von 'Untot' betroffen ist, erhält der Effekt 1 weiteren Stapel und springt außerdem auf einen weiteren Gegner in der Nähe über.\n\nUnheilig\nWenn einem Gegner Schaden zufügt, der von 'Untot' betroffen ist, erhält der Effekt 1 weiteren Stapel und springt außerdem auf einen weiteren Gegner in der Nähe über." }
