entries[444040] = { ["name"] = "Sofortige Apokalypse", ["text"] = "'Armee der Toten' und 'Furor des Frostwyrms' rufen für 20 Sek. alle vier Reiter zu Eurer Unterstützung herbei.\n(1s Abklingzeit)" }
entries[444043] = { ["name"] = "Flammen" }
entries[444044] = { ["name"] = "Blitzstrom", ["text"] = "Sofort\nBei Erreichen von 100 Energie fliegt Kyrioss in die Mitte des Raums und überlädt sich mit Blitzenergie, die 15 Sek. lang alle 3 Sek. 1212225 Naturschaden verursacht und ' Erdungsblitz ' auslöst. Entfesselt außerdem 4 Blitzströme. Das Berühren dieser Ströme verursacht 19395595 Naturschaden und betäubt das Ziel für 6 Sek." }
entries[444045] = { ["name"] = "Aufreißen", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Astrale schneidet durch das Ziel und fügt ihm 5 Schattenschaden zu." }
entries[444047] = { ["name"] = "Mograines Macht", ["text"] = "Frost\nEuer Schaden wird um 5% erhöht, und Ihr erhaltet 5% kritische Trefferchance, solange Ihr Euch in Mograines 'Tod und Verfall' aufhaltet.\n\nUnheilig\nEuer Schaden wird um 5% erhöht, und Ihr erhaltet die Vorteile von 'Tod und Verfall', solange Ihr Euch in Mograines 'Tod und Verfall' aufhaltet." }
