entries[444052] = { ["name"] = "Nazgrims Feldzug", ["text"] = "Wenn ein Gegner stirbt, solange Nazgrim aktiv ist, wird die Stärke von 'Apokalyptische Eroberung' um 3% erhöht.\n\nAußerdem erhöht jede Rune, die Ihr verbraucht, den Wert um 1%." }
entries[444055] = { ["name"] = "Blutraserei", ["text"] = "Nahkampfreichweite\nWirken in 2 sek.\nDer Zaubernde stürzt sich auf sein Ziel, um dessen Blut zu kosten, wodurch ihm körperlicher Schaden zugefügt und sein Angriffstempo erhöht wird." }
entries[444057] = { ["name"] = "Blitzstrom", ["text"] = "Sofort\nBei Erreichen von 100 Energie fliegt Kyrioss in die Mitte des Raums und überlädt sich mit Blitzenergie, die 15 Sek. lang alle 3 Sek. 1212225 Naturschaden verursacht und ' Erdungsblitz ' auslöst. Entfesselt außerdem 4 Blitzströme. Das Berühren dieser Ströme verursacht 19395595 Naturschaden und betäubt das Ziel für 6 Sek." }
entries[444061] = { ["name"] = "Zum Abschied winken" }
entries[444062] = { ["name"] = "Zum Abschied winken", ["text"] = "Sofort\nWinkt den anderen Irdenen zum Abschied und versichert ihnen, dass Ihr heil wiederkehren werdet." }
entries[444066] = { ["name"] = "Teleportieren", ["text"] = "Wirken in 5 sek.\nTeleportiert mithilfe eines Holosteins an einen anderen Ort." }
entries[444067] = { ["name"] = "Vertrag des Leerenschnitters", ["text"] = "Ca. 3 Procs pro Minute\nEure Fähigkeiten haben eine hohe Chance, ein Phantom zu beschwören, das Eurem Ziel ( 1 * 600 ) Schattenschaden und allen anderen Gegnern in seinem Weg [Quellwert] Schattenschaden zufügt.\n\nWenn sich das Ziel bei weniger als 35% Gesundheit befindet, beschwört dieser Effekt zwei zusätzliche Phantome mit 25% Effektivität.\n(1s Abklingzeit)", ["unresolvedValues"] = true }
entries[444068] = { ["name"] = "Armschienen der vordringenden Dunkelheit", ["text"] = "Wirken in 2 sek. 3\nReagenzien:\nPhiole voll Kahetiölen (2), Schwarmchitin der Kaheti (10), Zuckender Balg (2), Chitinrüstungsbänder , Funke (#256)\nOptionale Reagenzien:\nMit Energie erfüllen (#284) , Kettenrüstung (#287) , Authentizität des Kunsthandwerks (#346) , Weiter Augmentieren (#384)\nBeute von:\nWeltkreaturen\n\nUnterarmschienen der vordringenden Dunkelheit\nWird beim Aufheben gebunden\nHandgelenk Kette\n2317 Rüstung\n+1.198 [Beweglichkeit oder Intelligenz]+5.483 Ausdauer\n+ 351 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 468.\nHaltbarkeit 55 / 55\nAnlegen: Wenn Ihr Schaden verursacht, besteht eine Chance, einen Stapel von 'Verfinsternde Dunkelheit' zu erhalten. Bei 5 Stapeln explodiert die Dunkelheit und verursacht ( 1 * 161232 ) Schattenschaden, die auf alle Gegner in der Nähe aufgeteilt werden. Der Schaden erhöht sich pro Ziel für maximal 5 Ziele. Danach legen sich die Schatten auf Euch und verringern Eure Bewegungsgeschwindigkeit 5 Sek. lang um 15%.\n\nDies ist eine nerubische Verzierung.\n80" }
entries[444069] = { ["name"] = "Zorn der Reiter", ["text"] = "Wann immer Ihr 50 Runenmacht ausgebt, wird die 'Unterstützung der Reiter' im Kampf um 1 Sek. verlängert. Bis zu 5 Sek." }
entries[444070] = { ["name"] = "Schnalle des Adrenalinschubs", ["text"] = "Wirken in 2 sek. 3\nReagenzien:\nPhiole voll Kahetiölen (2), Schwarmchitin der Kaheti (10), Zuckender Balg (2), Chitinrüstungsbänder , Funke (#256)\nOptionale Reagenzien:\nMit Energie erfüllen (#284) , Lederrüstung (#286) , Authentizität des Kunsthandwerks (#346) , Weiter Augmentieren (#384)\nBeute von:\nSikran, Hauptmann der Sureki\nZone:\nPalast der Nerub'ar\nMuster:\nErhältlich im Auktionshaus\n\nSchnalle des Adrenalinschubs\nWird beim Aufheben gebunden\nTaille Leder\n1767 Rüstung\n+1.597 [Beweglichkeit oder Intelligenz]+7.311 Ausdauer\nErhöht Eure kritische Trefferwertung um + 624.\n+ 468 Vielseitigkeit\nHaltbarkeit 55 / 55\nAnlegen: Beim Erleiden von Schaden besteht eine Chance, dass Ihr 'Adrenalinschub' erhaltet, sodass Eure Hauptwert um 1265 erhöht, Eure Meisterschaft aber um 207 verringert wird. Hält 12 Sek. lang an.\n\nDies ist eine nerubische Verzierung. (15s Abklingzeit)\n80" }
entries[444071] = { ["name"] = "Watstiefel der vereinigenden Flamme", ["text"] = "Wirken in 2 sek. 3\nReagenzien:\nEntweihter Zunderkasten (2), Sturmgeladenes Leder (150), Kristallverschmolzener Balg (3), Chitinrüstungsbänder , Funke (#256)\nOptionale Reagenzien:\nMit Energie erfüllen (#284) , Lederrüstung (#286) , Authentizität des Kunsthandwerks (#346) , Weiter Augmentieren (#384)\nBeute von:\nPriorin Murrbet\nZone:\nPriorat der Heiligen Flamme\n\nWatstiefel der vereinigenden Flamme\nWird beim Aufheben gebunden\nFüße Leder\n1964 Rüstung\n+1.597 [Beweglichkeit oder Intelligenz]+7.311 Ausdauer\nErhöht Eure Tempowertung um + 624.\nErhöht Eure Meisterschaftswertung um + 468.\nHaltbarkeit 80 / 80\nAnlegen: Beim Heilen eines Verbündeten besteht eine Chance, dass Ihr beide eine vereinigende Glut erhaltet. Wenn sich zwei vereinigende Gluten berühren, brechen 'Vereinigende Flammen' daraus hervor.\n\n'Vereinigende Flammen' erhöht den höchsten Sekundärwert des Trägers um 1175 und bei anderen einen zufälligen Sekundärwert um 235 .\n80" }
entries[444072] = { ["name"] = "Festmahl der Seelen", ["text"] = "Wenn Euch mindestens 2 Reiter unterstützen, verursachen Eure Fähigkeiten, die Runenmacht kosten, 20% mehr Schaden." }
entries[444073] = { ["name"] = "Geheiligter Handschutz des Fackelträgers", ["text"] = "Wirken in 2 sek. 3\nReagenzien:\nEntweihter Zunderkasten (3), Düsternischitin (150), Kristallverschmolzener Balg (3), Chitinrüstungsbänder , Funke (#256)\nOptionale Reagenzien:\nMit Energie erfüllen (#284) , Kettenrüstung (#287) , Authentizität des Kunsthandwerks (#346) , Weiter Augmentieren (#384)\nQuest:\nVerbreitung des Lichts\n\nGeheiligter Handschutz des Fackelträgers\nWird beim Aufheben gebunden\nHände Kette\n2606 Rüstung\n+1.597 [Beweglichkeit oder Intelligenz]+7.311 Ausdauer\nErhöht Eure kritische Trefferwertung um + 624.\nErhöht Eure Meisterschaftswertung um + 468.\nHaltbarkeit 55 / 55\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, die Kraft des Lichts auf Eure Gegner herabzurufen. Ein Funke von Beledar richtet und markiert sie und fügt ihnen 86350 Strahlenschaden zu. Euer nächster Funke gegen Euer Ziel verbraucht das Mal, um 74015 zusätzlichen Strahlenschaden zu verursachen.\n80" }
entries[444074] = { ["name"] = "Unterstützung der Reiter", ["text"] = "Während die Reiter Euch unterstützen, wirken sie gelegentlich 'Antimagische Hülle' mit 80% Effektivität auf Euch und sich selbst.\n\nIhr könnt nur alle 45 Sek. von diesem Effekt profitieren." }
entries[444081] = { ["name"] = "Rotglühend", ["text"] = "'Umhüllen' erhält 1 zusätzliche Ladung und verursacht 20% mehr Schaden und Heilung." }
entries[444082] = { ["name"] = "Freiheit", ["text"] = "Erhöht die Vermeidung um 20%.\nEntfernt sofort Kontrollverlusteffekte von Verbündeten innerhalb von 40 Metern. Dieser Effekt kann nur einmal alle 45 Sek. auftreten." }
entries[444083] = { ["name"] = "Pakt der Apokalypse", ["text"] = "Wenn Ihr Schaden erleidet, werden 5% davon auf jeden aktiven Reiter umgeleitet." }
entries[444088] = { ["name"] = "Flamme verschlingen", ["text"] = "Verheerung\n'Umhüllen' zehrt 2 Sek. von 'Feueratem' auf dem Ziel auf, lässt es explodieren und fügt allen Zielen in der Nähe 900% der aufgezehrten Menge als Schaden zu. Bei Zielen über 5 Ziele hinaus ist der Effekt verringert.\n\nBewahrung\n'Umhüllen' zehrt 2 Sek. von 'Traumatem' auf dem Ziel auf, lässt es explodieren und fügt allen Zielen in der Nähe 300% der aufgezehrten Menge als Heilung zu. Bei Zielen über 5 Ziele hinaus ist der Effekt verringert." }
entries[444089] = { ["name"] = "Flamme verschlingen", ["text"] = "100 Meter Reichweite\nSofort\nVerheerung\n'Umhüllen' zehrt 2 Sek. von 'Feueratem' auf dem Ziel auf, lässt es explodieren und fügt allen Zielen in der Nähe 900% der aufgezehrten Menge als Schaden zu. Bei Zielen über 5 Ziele hinaus ist der Effekt verringert.\n\nBewahrung\n'Umhüllen' zehrt 2 Sek. von 'Traumatem' auf dem Ziel auf, lässt es explodieren und fügt allen Zielen in der Nähe 900% der aufgezehrten Menge als Heilung zu. Bei Zielen über 5 Ziele hinaus ist der Effekt verringert." }
entries[444094] = { ["name"] = "Ätzender Hagel", ["text"] = "Unbegrenzte Reichweite\nSofort\nRasha'nan lässt Säure regnen und fügt allen Spielercharakteren, die sich im Umkreis von 4 Metern um den Einschlagsort befinden, 3453789 Naturschaden zu und erschafft gelegentlich Säurepfützen." }
entries[444095] = { ["name"] = "Illusionen zermalmen", ["text"] = "13 Meter Reichweite\nWirken in 4 sek.\nEntfernt den ablenkenden Köder." }
entries[444096] = { ["name"] = "Winterfin Tadpole Cage Opened - Player Cast" }
entries[444097] = { ["name"] = "Trollbanns eisiger Zorn", ["text"] = "Frost\n'Auslöschen' und 'Frostsichel' zersplittern bei einem Treffer Trollbanns 'Eisketten', was Gegnern in der Nähe (140.4% der Angriffskraft) Schattenfrostschaden zufügt und sie 4 Sek. lang um 40% verlangsamt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nUnheilig\nzersplittert bei einem Treffer Trollbanns 'Eisketten', was Gegnern in der Nähe (140.4% der Angriffskraft) Schattenfrostschaden zufügt und sie 4 Sek. lang um 40% verlangsamt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu." }
entries[444099] = { ["name"] = "Schlundgebundene Bedrohung", ["text"] = "Frost\n'Auslöschen' verursacht 5% mehr Schaden und 'Unbarmherziger Winter' hält 2 Sek. länger an.\n\nUnheilig\n% mehr Schaden und die Abklingzeit von 'Tod und Verfall' ist um 5 Sek. verringert." }
