entries[444223] = { ["name"] = "Algarische Ingenieurskunstabhandlung", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nZappelnde Probe (2), Unbändige Chiffre , Schattentinte (2)\nBeruf:\nHandwerksentdeckung durch Abhandlungen\n\nAlgarische Ingenieurskunstabhandlung\nWird an Kriegsmeute gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen von Khaz Algar um 1 zu erhöhen.\nBenötigt Ingenieurskunst von Khaz Algar\n(25)" }
entries[444224] = { ["name"] = "Umschreiben: Aszendenz", ["text"] = "Wirken in 1 sek.\nReagenzien:\nSchattentinte\nSchreibt 2 derselben Dunkelmond-Karte aus Khaz Algar in eine Karte der Aszendenz um.\nSpezialisierung:\nArchivergänzungen - Dunkelmondsiegel: Aszendenz (30)" }
entries[444225] = { ["name"] = "Umschreiben: Lebhaftigkeit", ["text"] = "Wirken in 1 sek.\nReagenzien:\nSchattentinte\nSchreibt 2 derselben Dunkelmond-Karte aus Khaz Algar in eine Karte der Lebhaftigkeit um.\nSpezialisierung:\nArchivergänzungen - Dunkelmondsiegel: Lebhaftigkeit (30)" }
entries[444226] = { ["name"] = "Umschreiben: Symbiose", ["text"] = "Wirken in 1 sek.\nReagenzien:\nSonnige Tinte\nSchreibt 2 derselben Dunkelmond-Karte aus Khaz Algar in eine Karte der Symbiose um.\nSpezialisierung:\nArchivergänzungen - Dunkelmondsiegel: Symbiose (30)" }
entries[444227] = { ["name"] = "Umschreiben: Glanz", ["text"] = "Wirken in 1 sek.\nReagenzien:\nSonnige Tinte\nSchreibt 2 derselben Dunkelmond-Karte aus Khaz Algar in eine Karte des Glanzes um.\nSpezialisierung:\nArchivergänzungen - Dunkelmondsiegel: Glanz (30)" }
entries[444236] = { ["name"] = "Algarische Kürschnereiabhandlung", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nGrünliche Sporen (2), Unbändige Chiffre , Sonnige Tinte (2)\nBeruf:\nHandwerksentdeckung durch Abhandlungen\n\nAlgarische Kürschnereiabhandlung\nWird an Kriegsmeute gebunden\nBenutzen: Studieren, um Euer Kürschnereiwissen von Khaz Algar um 1 zu erhöhen. (5 Sek. Abklingzeit)\nBenötigt Kürschnerei von Khaz Algar\n(25)" }
