entries[444244] = { ["name"] = "Sofortige Apokalypse", ["text"] = "Sofort\n'Armee der Toten' und 'Furor des Frostwyrms' rufen für 20 Sek. alle vier Reiter zu Eurer Unterstützung herbei." }
entries[444245] = { ["name"] = "Zutatenquestgeber beschwören" }
entries[444246] = { ["name"] = "Zutatenquestgeber beschwören", ["text"] = "10 Meter Reichweite\nSofort\nAktivieren, um ein Ziel auszuwählen." }
entries[444247] = { ["name"] = "Stromschlag", ["text"] = "100 Meter Reichweite\nSofort\nVon einem Schuppenlader betäubt." }
entries[444248] = { ["name"] = "Mograine beschwören", ["text"] = "Sofort\nBeim Verbrauchen von Runen habt Ihr die Chance, 10 Sek. lang die Hilfe eines Reiters zu erhalten.\n\nMograine\nWirkt 'Tod und Verfall' an seiner Position. Der Effektbereich folgt seiner Bewegung.\n\nWeißsträhne\nWirkt 'Untot' auf Euer Ziel, was 24 Sek. lang alle 3 Sek. pro Stapel (9.15376% der Angriffskraft) Schattenfrostschaden verursacht. Wann immer 'Untot' Schaden verursacht, wird das Ziel mit einem weiteren Stapel belegt. Kann nicht erneuert werden.\n\nTrollbann\nWirkt 'Eisketten' auf Euer Ziel, was 8 Sek. lang dessen Bewegungsgeschwindigkeit um 40% verringert und den Schaden, den Ihr ihm zufügt, um 5% erhöht.\n\nNazgrim\nWährend Nazgrim aktiv ist, erhaltet Ihr 'Apokalyptische Eroberung', was Eure Stärke um 5% erhöht." }
entries[444249] = { ["name"] = "Feueratem", ["text"] = "100 Meter Reichweite\nSofort\nAtmet ein und facht Euer inneres Feuer an. Setzt den Atem frei, um Gegner in einem kegelförmigen Bereich vor Euch zu verbrennen und ihnen [((163.409% der Zaubermacht)) + ((39.4834% der Zaubermacht) * (10 + 0 ))] Feuerschaden zuzufügen. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. [ Sande der Zeit : Erhöht die Dauer Eurer aktiven Effekte von 'Schwarzmacht' um 2 Sek ]\nBei Ermächtigung wird ein höherer Anteil des Schadens sofort anstatt als regelmäßiger Schaden verursacht.\n\nI: Verursacht sofort [(163.409% der Zaubermacht)] Schaden und [(39.4834% der Zaubermacht) * (10 + 0 )] Schaden im Verlauf von (20 + 0 ) Sek.\n\nII: Verursacht sofort [(163.409% der Zaubermacht) + ((39.4834% der Zaubermacht) * 3)] Schaden und [(39.4834% der Zaubermacht) * (7 + 0 )] Schaden im Verlauf von (14 + 0 ) Sek.\n\nIII: Verursacht sofort [(163.409% der Zaubermacht) + ((39.4834% der Zaubermacht) * 6)] Schaden und [(39.4834% der Zaubermacht) * (4 + 0 )] Schaden im Verlauf von (8 + 0 ) Sek." }
entries[444250] = { ["name"] = "Blitzstrom", ["text"] = "Unbegrenzte Reichweite\nSofort\nBei Erreichen von 100 Energie fliegt Kyrioss in die Mitte des Raums und überlädt sich mit Blitzenergie, die 15 Sek. lang alle 3 Sek. 1212225 Naturschaden verursacht und ' Erdungsblitz ' auslöst. Entfesselt außerdem 4 Blitzströme. Das Berühren dieser Ströme verursacht 19395595 Naturschaden und betäubt das Ziel für 6 Sek." }
entries[444251] = { ["name"] = "Weißsträhne beschwören", ["text"] = "Sofort\nBeim Verbrauchen von Runen habt Ihr die Chance, 10 Sek. lang die Hilfe eines Reiters zu erhalten.\n\nMograine\nWirkt 'Tod und Verfall' an seiner Position. Der Effektbereich folgt seiner Bewegung.\n\nWeißsträhne\nWirkt 'Untot' auf Euer Ziel, was 24 Sek. lang alle 3 Sek. pro Stapel (9.15376% der Angriffskraft) Schattenfrostschaden verursacht. Wann immer 'Untot' Schaden verursacht, wird das Ziel mit einem weiteren Stapel belegt. Kann nicht erneuert werden.\n\nTrollbann\nWirkt 'Eisketten' auf Euer Ziel, was 8 Sek. lang dessen Bewegungsgeschwindigkeit um 40% verringert und den Schaden, den Ihr ihm zufügt, um 5% erhöht.\n\nNazgrim\nWährend Nazgrim aktiv ist, erhaltet Ihr 'Apokalyptische Eroberung', was Eure Stärke um 5% erhöht." }
entries[444252] = { ["name"] = "Nazgrim beschwören", ["text"] = "Sofort\nBeim Verbrauchen von Runen habt Ihr die Chance, 10 Sek. lang die Hilfe eines Reiters zu erhalten.\n\nMograine\nWirkt 'Tod und Verfall' an seiner Position. Der Effektbereich folgt seiner Bewegung.\n\nWeißsträhne\nWirkt 'Untot' auf Euer Ziel, was 24 Sek. lang alle 3 Sek. pro Stapel (9.15376% der Angriffskraft) Schattenfrostschaden verursacht. Wann immer 'Untot' Schaden verursacht, wird das Ziel mit einem weiteren Stapel belegt. Kann nicht erneuert werden.\n\nTrollbann\nWirkt 'Eisketten' auf Euer Ziel, was 8 Sek. lang dessen Bewegungsgeschwindigkeit um 40% verringert und den Schaden, den Ihr ihm zufügt, um 5% erhöht.\n\nNazgrim\nWährend Nazgrim aktiv ist, erhaltet Ihr 'Apokalyptische Eroberung', was Eure Stärke um 5% erhöht." }
entries[444254] = { ["name"] = "Trollbann beschwören", ["text"] = "Sofort\nBeim Verbrauchen von Runen habt Ihr die Chance, 10 Sek. lang die Hilfe eines Reiters zu erhalten.\n\nMograine\nWirkt 'Tod und Verfall' an seiner Position. Der Effektbereich folgt seiner Bewegung.\n\nWeißsträhne\nWirkt 'Untot' auf Euer Ziel, was 24 Sek. lang alle 3 Sek. pro Stapel (9.15376% der Angriffskraft) Schattenfrostschaden verursacht. Wann immer 'Untot' Schaden verursacht, wird das Ziel mit einem weiteren Stapel belegt. Kann nicht erneuert werden.\n\nTrollbann\nWirkt 'Eisketten' auf Euer Ziel, was 8 Sek. lang dessen Bewegungsgeschwindigkeit um 40% verringert und den Schaden, den Ihr ihm zufügt, um 5% erhöht.\n\nNazgrim\nWährend Nazgrim aktiv ist, erhaltet Ihr 'Apokalyptische Eroberung', was Eure Stärke um 5% erhöht." }
entries[444256] = { ["name"] = "Splitternde Kugeln", ["text"] = "Arkan\nGegner, denen Ihr mit 'Arkane Kugel' Schaden zufügt, beschwören 2 arkane Splitter (bis zu 4).\n\nDer Schaden von 'Arkane Kugel' ist um 25% erhöht.\n\nFrost\nGegner, denen Ihr mit 'Gefrorene Kugel' Schaden zufügt, beschwören 1 Frostsplitter (bis zu 4).\n\n'Gefrorene Kugel' ist um 25% erhöht." }
entries[444257] = { ["name"] = "Donnernde Trommeln", ["text"] = "Sofort 5 min Abklingzeit\nErhöht das Tempo aller Gruppen- und Schlachtzugsmitglieder um 15%. Hält 40 Sek. lang an.\n\nWenn der Effekt endet, sind die Betroffenen erschöpft und können 10 Min. lang nicht mehr von 'Kampfrausch', 'Heldentum' oder ähnlichen Effekten profitieren." }
entries[444258] = { ["name"] = "Beißwerkzeug des besudelten Behemoths", ["text"] = "(900ms Abklingzeit)" }
entries[444260] = { ["name"] = "Fesselzahn", ["text"] = "Nahkampfreichweite\nWirken in 1.5 sek.\nDer Zaubernde beißt sein aktuelles Ziel und bespuckt es mit Spinnweben, was diesem Naturschaden zufügt und ihn 5 Sek. lang verlangsamt." }
entries[444263] = { ["name"] = "Instabile Explosion", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Zaubernde explodiert und fügt Gegnern innerhalb von 4 Metern 2878158 Naturschaden zu." }
entries[444264] = { ["name"] = "Verdauungsgift", ["text"] = "6 Meter Reichweite\nSofort 1.5 min Abklingzeit\nInjiziert einem Gegner ein Verdauungsgift und fügt ihm im Verlauf von 20 Sek. 2330 Naturschaden zu. Solange es aktiv ist, stellen Eure Angriffe und Fähigkeiten gegen das Ziel 121 Gesundheit wieder her. Kann nur ein Mal pro Sekunde auftreten.\n\nÜberheilung durch diesen Effekt erhöht dauerhaft Eure maximale Gesundheit um den gleichen Wert. Der Effekt wird nach Verlassen des Kampfes in ein Absorptionsschild umgewandelt." }
entries[444265] = { ["name"] = "Kompass der Familie Bronzebart" }
entries[444266] = { ["name"] = "Kompass der Familie Bronzebart", ["text"] = "Sofort 2 min Abklingzeit\nOrientiert Euch und trefft Euch mit Brann, der heldenhaft heranrauscht und '' einsetzt. Er verursacht dadurch 12435 körperlichen Schaden und gewährt Euch dann 10 Sek. lang 305 Hauptwert, bevor er wieder verschwindet.\n\nSollte Brann bereits an Euer Seite sein, wird er Euch stolz den Weg zum Abenteuer weisen! Dafür bewegt er sich an eine andere Stelle, verleiht sich selbst 10 Sek. lang 50% zusätzlichen Schaden und setzt '' ein.\n\n:" }
entries[444269] = { ["name"] = "Schattenwoge", ["text"] = "100 Meter Reichweite\nSofort\nRegelmäßiger Schaden von 'Schwarzer Pfeil' hat eine geringe Chance, in einer Explosion von Dunkelheit auszubrechen, die allen Gegnern in der Nähe des Ziels (75% der Angriffskraft) Schattenschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu." }
entries[444270] = { ["name"] = "Azeroths Stimme", ["text"] = "Sofort\nAzeroth ruft Euch." }
entries[444271] = { ["name"] = "Kriechendes Koagulum" }
entries[444274] = { ["name"] = "Lampenanzünderfeuerwaffe", ["text"] = "Kanalisiert (Wirken in 5 sek.)\nAktiviert die Lampenanzünderfeuerwaffe, die Motteneier vor dem Zaubernden in Brand setzt." }
entries[444276] = { ["name"] = "Grausame Spritze", ["text"] = "Ca. 6 Procs pro Minute\nBei Euren Heilzaubern besteht eine hohe Chance, dass Ihr Euch eine Aufladung ' Instabiles Serum ' injiziert. Mehrere Aufladungen können sich überschneiden.\n\nWenn ein Verbündeter unter 70% Gesundheit fällt, stoßt Ihr eine Aufladung aus und heilt ihn um 2146 Gesundheit. Aufladungen, die nach 15 Sek. noch nicht verbraucht wurden, werden katalysiert und gewähren Euch stattdessen 10 Sek. lang 58 Intelligenz." }
entries[444277] = { ["name"] = "Lampenanzünderfeuerwaffe" }
entries[444278] = { ["name"] = "Formen", ["text"] = "Wirken in 5 sek.\nRein in die Form und dann mit Töpferkunst angeben!" }
entries[444282] = { ["name"] = "Kriechendes Koagulum", ["text"] = "Sofort 1.5 min Abklingzeit\nFüttert das Koagulum und leitet 20% sämtlicher hervorgerufener Heilung um bis ( 10669 * 40 / 100) Heilung aufgezehrt wurde. Ist es gesättigt, bricht das Koagulum auf und heilt 5 Verbündete um [Quellwert] Gesundheit.\n\nAnhaltende Ausdünstungen lassen die nächsten Angriffe betroffener Verbündeter basierend auf der überschüssigen Heilung durch das Koagulum 76 zusätzlichen Schattenschaden verursachen.", ["unresolvedValues"] = true }
