entries[444292] = { ["name"] = "Autorität des Schwarmfürsten", ["text"] = "Ca. 3 Procs pro Minute\nEure Angriffe und Fähigkeiten haben eine hohe Chance, einen Skarabäus zu beschwören, der ein stärkendes Fleischstück aus Eurem Ziel reißt. Skarabäen verursachen 62 körperlicher Schaden und verringern Euren erlittenen Schaden um 50% bis 1539 Schaden verhindert wurde." }
