entries[444296] = { ["name"] = "Durchbohren", ["text"] = "40 Meter Reichweite\nSofort\nDurchbohrt ein zufälliges Ziel und verursacht 8 körperlichen Schaden sowie zusätzlich bis Abbruch lang alle 5.2 Sek. 8 körperlichen Blutungsschaden." }
