entries[444301] = { ["name"] = "Gefräßiger Schwarm", ["text"] = "40 Meter Reichweite\nSofort 1 min Abklingzeit\nBringt Euren Schwarm zur Raserei und beschwört im Verlauf von 3 Sek. 12 Skarabäen, die Eure Gegner heimsuchen. Die Anzahl der Skarabäen wird durch Euer Tempo erhöht." }
