entries[444306] = { ["name"] = "Abyssalleitung", ["text"] = "Unbegrenzte Reichweite\nSofort\nLeerenleitungen brechen auf und fügen Spielercharakteren innerhalb von 10 Metern 8634473 Schattenschaden zu und führen zu einem ' Leitungsausstoß '.\n\nDie Leitungen teleportieren Spielercharaktere bei Berührung und verursachen 575632 Schattenschaden und belegen sie mit ' Abyssischer Nachhall '.\n\nWenn diese Leitungen destabilisiert werden, kommt es zu einem ' Leitungskollaps '." }
